        self.dim = dim
        self.population_size = population_size
        self.mutation_rate = mutation_rate
        self.crossover_rate = crossover_rate
        self.initial_search_radius = initial_search_radius
        self.search_radius = initial_search_radius
        self.lb = -5.0
        self.ub = 5.0
        self.eval_count = 0
        self.diversity_threshold = diversity_threshold


    def initialize_population(self):
        return np.random.uniform(self.lb, self.ub, size=(self.population_size, self.dim))

    def evaluate_fitness(self, func, population):
        fitness = np.array([func(x) for x in population])
        self.eval_count += self.population_size
        return fitness

    def select_parents(self, population, fitness):
        # Tournament selection
        indices = np.arange(len(population))
        np.random.shuffle(indices)
        parent_indices = []
        for i in range(self.population_size):
            idx1 = indices[i]
            idx2 = indices[(i + 1) % self.population_size]  # ensure distinct indices
            if fitness[idx1] < fitness[idx2]:
                parent_indices.append(idx1)
            else:
                parent_indices.append(idx2)
        return population[parent_indices]

    def crossover(self, parents):
        offspring = []
        for i in range(0, len(parents), 2):
            if np.random.rand() < self.crossover_rate and i + 1 < len(parents):
                # Single-point crossover
                crossover_point = np.random.randint(1, self.dim)
                parent1 = parents[i]
                parent2 = parents[i+1]
                child1 = np.concatenate((parent1[:crossover_point], parent2[crossover_point:]))
                child2 = np.concatenate((parent2[:crossover_point], parent1[crossover_point:]))
                offspring.extend([child1, child2])
            else:
                offspring.append(parents[i])
                if i + 1 < len(parents):
                    offspring.append(parents[i+1])
        return np.array(offspring)

    def mutate(self, population):
        for i in range(len(population)):
            if np.random.rand() < self.mutation_rate:
                mutation_indices = np.random.randint(0, self.dim, size=np.random.randint(1, self.dim + 1)) # Mutate at least 1 dimension
                population[i, mutation_indices] = np.random.uniform(self.lb, self.ub, size=len(mutation_indices))
        return population

    def adaptive_neighborhood_search(self, func, individual):
        if self.eval_count >= self.budget:
            return individual

        best_individual = individual
        best_fitness = func(individual)
        self.eval_count += 1

        # Adaptive Search Radius
        search_radius = self.search_radius

        for _ in range(10):  # Limited iterations for the local search
            neighbor = best_individual + np.random.uniform(-search_radius, search_radius, size=self.dim)
            neighbor = np.clip(neighbor, self.lb, self.ub)

            if self.eval_count >= self.budget:
                break

            fitness = func(neighbor)
            self.eval_count += 1
            if fitness < best_fitness:
                best_fitness = fitness
                best_individual = neighbor
        return best_individual

    def calculate_diversity(self, population):
        if len(population) <= 1:
            return 1.0  # High diversity if only one or no individual
        distances = pdist(population)
        if len(distances) == 0:
            return 1.0 # Handle the case where all individuals are identical
        return np.mean(distances) / (np.sqrt(self.dim))


    def __call__(self, func):
        population = self.initialize_population()
        best_fitness = np.inf
        best_solution = None

        while self.eval_count < self.budget:
            fitness = self.evaluate_fitness(func, population)

            # Keep track of best solution
            for i, f in enumerate(fitness):
                if f < best_fitness:
                    best_fitness = f
                    best_solution = population[i]

            # Calculate Diversity
            diversity = self.calculate_diversity(population)

            # Adjust search radius based on population diversity
            if diversity < self.diversity_threshold:
                self.search_radius *= 0.8  # Reduce search radius if low diversity (exploitation)
            else:
                self.search_radius *= 1.2 # Increase search radius if high diversity (exploration)

            self.search_radius = np.clip(self.search_radius, 1e-6, 2.0) #Clamp search radius

            parents = self.select_parents(population, fitness)
            offspring = self.crossover(parents)
            offspring = self.mutate(offspring)


            # Neighborhood search on promising individuals
            for i in range(len(offspring)):
                if self.eval_count < self.budget:
                    offspring[i] = self.adaptive_neighborhood_search(func, offspring[i])
                    fitness_offspring = func(offspring[i])
                    self.eval_count +=1
                    if fitness_offspring < best_fitness:
                        best_fitness = fitness_offspring
                        best_solution = offspring[i]

            population = offspring  # Replace population with offspring

        return best_fitness, best_solution
